<?php
$money = static fn($value): string => number_format((float) $value, 0, ',', '.') . '₫';
$date = static fn($value): string => $value ? date('d/m/Y', strtotime((string) $value)) : '';
$steps = ['confirmed' => 'Đã xác nhận', 'shipping' => 'Đang vận chuyển', 'completed' => 'Đã giao'];
?>
<!doctype html>
<html lang="vi">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Đơn hàng của tôi · HHDM</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f6f7f8;color:#202124;font:14px Arial,sans-serif}.top{height:62px;background:#fff;border-bottom:1px solid #eee;display:flex;align-items:center;justify-content:space-between;padding:0 max(20px,calc((100vw - 1080px)/2));position:sticky;top:0}.brand{color:#222;text-decoration:none;font:700 22px Georgia,serif}.top a:last-child{color:#555;text-decoration:none;font-size:13px}.wrap{max-width:960px;margin:34px auto;padding:0 18px}.title{font:500 32px Georgia,serif;margin:0 0 6px}.intro{color:#747780;margin:0 0 24px}.order{background:#fff;border:1px solid #eceef0;border-radius:10px;margin:14px 0;padding:20px 22px;box-shadow:0 2px 10px #25282008}.order-head{display:flex;justify-content:space-between;gap:14px;border-bottom:1px solid #eee;padding-bottom:14px}.order-id{font-weight:700}.status{font-size:12px;color:#59654d;background:#f0f4ed;padding:7px 10px;border-radius:20px;white-space:nowrap}.status.pending{color:#8c6b2e;background:#fbf4e5}.status.cancelled{color:#985050;background:#fbebeb}.timeline{display:grid;grid-template-columns:repeat(3,1fr);margin:24px 0 20px;position:relative}.timeline:before{content:"";height:2px;background:#e7e9e5;position:absolute;top:9px;left:8%;right:8%}.step{position:relative;text-align:center;color:#969a92;font-size:11px}.dot{width:19px;height:19px;border:2px solid #ddd;background:#fff;border-radius:50%;display:block;margin:0 auto 8px;position:relative;z-index:1}.step.done{color:#46553c;font-weight:700}.step.done .dot{background:#58644b;border-color:#58644b;box-shadow:inset 0 0 0 4px #fff}.eta{background:#f4f7f1;color:#485641;border-radius:7px;padding:12px 14px;margin:14px 0;font-size:13px}.details{display:grid;grid-template-columns:1fr 1fr;gap:12px 22px;color:#555;font-size:12px;line-height:1.6}.details strong{display:block;color:#282a27;font-size:11px;margin-bottom:3px}.items{border-top:1px solid #eee;margin-top:16px;padding-top:12px}.item{display:flex;justify-content:space-between;gap:12px;padding:5px 0;font-size:12px}.voucher{margin-top:16px;padding:14px;background:#fff8e8;border:1px dashed #e4a727;border-radius:8px}.voucher strong{color:#775300}.voucher-code{display:inline-block;margin:8px 0 4px;padding:8px 12px;background:#fff;border:1px dashed #dba326;font:bold 15px monospace;letter-spacing:.05em}.muted{font-size:11px;color:#777}.empty{padding:36px;text-align:center;background:#fff;border-radius:10px;color:#777}.back{color:#58644b;text-decoration:none;font-weight:700}@media(max-width:600px){.wrap{margin:22px auto}.order{padding:16px}.details{grid-template-columns:1fr}.order-head{align-items:flex-start}.step{font-size:10px}}
