<body><header class="top"><a class="brand" href="index.php?page=home">HHDM FASHION</a><a href="index.php?page=home">← Tiếp tục mua sắm</a></header>
<main class="wrap"><h1 class="title">Đơn hàng của tôi</h1><p class="intro">Theo dõi trạng thái, thanh toán, vận chuyển và yêu cầu hủy đơn.</p>
<?php if (!empty($flash)): ?><div class="eta"><?= $escape($flash) ?></div><?php endif; ?>
<?php if (!$orders): ?><div class="empty">Bạn chưa có đơn hàng nào. <a class="back" href="index.php?page=home">Khám phá sản phẩm</a></div><?php endif; ?>
<?php foreach ($orders as $order):
  $progress = array_search($order['status'], ['confirmed', 'shipping', 'completed'], true);
  $statusLabel = ['pending' => 'Chờ thanh toán', 'confirmed' => 'Đã xác nhận', 'shipping' => 'Đang giao hàng', 'completed' => 'Đã giao', 'cancelled' => 'Đã hủy'][$order['status']] ?? $order['status'];
?>
<article class="order"><div class="order-head"><div><div class="order-id">Đơn #<?= (int) $order['order_id'] ?></div><div class="muted">Đặt ngày <?= $escape(date('d/m/Y H:i', strtotime($order['order_date']))) ?></div></div><span class="status <?= $escape($order['status']) ?>"><?= $escape($statusLabel) ?></span></div>
<?php if ($order['status'] === 'cancelled'): ?><p class="muted">Đơn hàng đã được hủy.</p>
<?php elseif ($order['status'] === 'pending'): ?><div class="eta">Đơn hàng đang chờ xác nhận thanh toán. Thời gian giao sẽ được tính sau khi thanh toán thành công.</div>
<?php else: ?><div class="timeline"><?php foreach ($steps as $stepKey => $stepLabel): $stepIndex = array_search($stepKey, array_keys($steps), true); ?><div class="step <?= $progress !== false && $stepIndex <= $progress ? 'done' : '' ?>"><span class="dot"></span><?= $escape($stepLabel) ?></div><?php endforeach; ?></div>
<?php if ($order['expected_delivery_to']): ?><div class="eta"><?php if ($order['status'] === 'completed'): ?>Đã giao ngày <strong><?= $escape($date($order['delivered_at'])) ?></strong>.<?php else: ?>Dự kiến nhận hàng từ <strong><?= $escape($date($order['expected_delivery_from'])) ?> đến <?= $escape($date($order['expected_delivery_to'])) ?></strong>.<?php endif; ?></div><?php endif; ?>
<?php endif; ?>
<div class="details"><div><strong>NGƯỜI NHẬN</strong><?= $escape($order['recipient_name']) ?> · <?= $escape($order['recipient_phone']) ?></div><div><strong>ĐỊA CHỈ GIAO HÀNG</strong><?= nl2br($escape($order['shipping_address'])) ?></div>
<div><strong>THANH TOÁN</strong><?= ($order['payment_method'] ?? '') === 'cod' ? (!empty($order['cod_collected_at']) ? 'COD đã thu lúc ' . $escape(date('d/m/Y H:i', strtotime($order['cod_collected_at']))) : 'Thanh toán khi nhận hàng (COD)') : (($order['payment_status'] ?? '') === 'paid' ? 'Đã thanh toán' : 'Chưa thanh toán') ?></div>
<?php if ($order['shipping_company'] || $order['tracking_number']): ?><div><strong>VẬN CHUYỂN</strong><?= $escape($order['shipping_company'] ?: 'Đơn vị vận chuyển') ?><?= $order['tracking_number'] ? ' · Mã vận đơn ' . $escape($order['tracking_number']) : '' ?></div><?php endif; ?>
<?php if (!empty($order['shipped_at'])): ?><div><strong>BÀN GIAO ĐƠN VỊ VẬN CHUYỂN</strong>Đã xác nhận lúc <?= $escape(date('d/m/Y H:i', strtotime((string) $order['shipped_at']))) ?></div><?php endif; ?>
<div><strong>TỔNG THANH TOÁN</strong><?= $money($order['total_amount']) ?></div></div>
<?php if (in_array($order['status'], ['pending', 'confirmed'], true) && empty($order['shipped_at']) && in_array(($order['cancel_request_status'] ?? 'none'), ['none', 'rejected'], true)): ?>
<form method="post" action="index.php?page=update_order_details" class="eta"><strong>Sửa thông tin nhận hàng</strong><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="order_id" value="<?= (int) $order['order_id'] ?>"><label style="display:block;margin:8px 0">Người nhận<input name="recipient" maxlength="150" value="<?= $escape($order['recipient_name']) ?>" required style="display:block;width:100%;margin-top:4px"></label><label style="display:block;margin:8px 0">Số điện thoại<input name="phone" maxlength="20" value="<?= $escape($order['recipient_phone']) ?>" required style="display:block;width:100%;margin-top:4px"></label><label style="display:block;margin:8px 0">Địa chỉ<textarea name="address" maxlength="500" required style="display:block;width:100%;min-height:60px;margin-top:4px"><?= $escape($order['shipping_address']) ?></textarea></label><button class="back" type="submit">LƯU THÔNG TIN NHẬN HÀNG</button></form>
<?php endif; ?>
<?php if (!empty($order['note'])): ?><div class="eta">Ưu đãi đã áp dụng: <?= $escape($order['note']) ?></div><?php endif; ?>
<div class="items"><strong>SẢN PHẨM</strong><?php foreach ($order['items'] as $item): ?><div class="item"><span><?= $escape($item['product_name']) ?> · <?= $escape($item['size']) ?> × <?= (int) $item['quantity'] ?></span><strong><?= $money($item['subtotal']) ?></strong></div><?php endforeach; ?></div>
<?php if (($order['cancel_request_status'] ?? 'none') === 'requested'): ?><div class="eta">Yêu cầu hủy đang chờ cửa hàng xem xét. Lý do: <?= $escape($order['cancel_reason'] ?? '') ?></div>
<?php elseif (($order['cancel_request_status'] ?? '') === 'rejected'): ?><div class="eta">Cửa hàng chưa chấp thuận hủy đơn. <?= $escape($order['cancel_admin_note'] ?? '') ?></div>
<?php elseif ($order['status'] === 'cancelled'): ?><div class="eta">Đơn đã hủy. <?= $escape($order['cancel_reason'] ?? '') ?> <?= ($order['refund_status'] ?? 'none') === 'pending' ? 'Khoản thanh toán đang chờ cửa hàng hoàn.' : (($order['refund_status'] ?? '') === 'refunded' ? 'Cửa hàng đã ghi nhận hoàn tiền.' : '') ?> <?= $escape($order['refund_note'] ?? '') ?></div>
<?php elseif (in_array($order['status'], ['pending', 'confirmed'], true) && empty($order['shipped_at']) && in_array(($order['cancel_request_status'] ?? 'none'), ['none', 'rejected'], true)): ?>
<form method="post" action="index.php?page=request_order_cancellation" class="eta"><strong>Yêu cầu hủy đơn</strong><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="order_id" value="<?= (int) $order['order_id'] ?>"><label style="display:block;margin:8px 0">Lý do hủy<textarea name="reason" maxlength="500" required style="display:block;width:100%;min-height:60px;margin-top:5px"></textarea></label><button class="back" type="submit">GỬI YÊU CẦU HỦY</button><small style="display:block;margin-top:6px">Đơn chỉ được hủy sau khi cửa hàng duyệt.</small></form>
<?php endif; ?>
<?php foreach ($order['vouchers'] as $voucher): ?><div class="voucher"><strong>Voucher giao trễ · Giảm <?= (int) $voucher['discount_percent'] ?>% cho <?= $escape($voucher['product_name']) ?></strong><br><code class="voucher-code"><?= $escape($voucher['code']) ?></code><br><span class="muted">Nhập mã này khi mua lại đúng sản phẩm trước <?= $escape($date($voucher['expires_at'])) ?>. Trạng thái: <?= $voucher['status'] === 'available' ? 'Chưa sử dụng' : ($voucher['status'] === 'redeemed' ? 'Đã sử dụng' : ($voucher['status'] === 'expired' ? 'Đã hết hạn' : 'Đang áp dụng')) ?>.</span></div><?php endforeach; ?>
</article><?php endforeach; ?>
